import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';
import PageStructure from 'flarum/forum/components/PageStructure';
import IndexSidebar from 'flarum/forum/components/IndexSidebar';
import Icon from 'flarum/common/components/Icon';
import Avatar from 'flarum/common/components/Avatar';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Placeholder from 'flarum/common/components/Placeholder';
import Button from 'flarum/common/components/Button';
import Link from 'flarum/common/components/Link';
import username from 'flarum/common/helpers/username';
import humanTime from 'flarum/common/helpers/humanTime';
import textContrastClass from 'flarum/common/helpers/textContrastClass';
import { t, text, label, types, loadTypes, collectionUrl } from '../util';
import addToMyCollection from '../copyItem';
import { collectionCard, cover } from './bits';
import ItemModal from './ItemModal';
import useStyles from '../styles';

/**
 * /collections: what this forum collects. Two looks, the admin's choice: the
 * types as Flarum's own tags page tiles (the default), or as cover tiles.
 */
export default class BrowsePage extends Page {
  oninit(vnode) {
    super.oninit(vnode);
    useStyles();
    this.bodyClass = 'App--curio';
    this.overview = null;
    this.recent = null;
    this.collections = null;
    this.typeId = m.route.param('type') || null;
    this.q = '';
    this.found = null;
    app.history.push('curio.browse', text('browse.title'));
    app.setTitle(text('browse.title'));
    loadTypes();
    app.request({
      method: 'GET',
      url: `${app.forum.attribute('apiUrl')}/curio/overview`
    }).then(o => {
      this.overview = o;
      m.redraw();
    });
    app.store.find('curio-items', {
      filter: {
        status: 'owned'
      },
      include: 'collection.user,collection.type',
      sort: '-createdAt',
      page: {
        limit: 12
      }
    }).then(items => {
      this.recent = items;
      m.redraw();
    });
    this.loadCollections();
  }
  loadCollections() {
    this.collections = null;
    const query = this.typeId ? {
      filter: {
        type: this.typeId
      },
      sort: '-ownedCount',
      page: {
        limit: 24
      }
    } : {
      filter: {
        featured: '1'
      },
      sort: '-featuredAt',
      page: {
        limit: 12
      }
    };
    app.store.find('curio-collections', query).then(found => {
      // No collection featured yet: the biggest public ones stand in.
      if (!found.length && !this.typeId) {
        return app.store.find('curio-collections', {
          sort: '-ownedCount',
          page: {
            limit: 12
          }
        }).then(biggest => {
          this.collections = biggest;
          m.redraw();
        });
      }
      this.collections = found;
      m.redraw();
    });
  }
  search(q) {
    this.q = q;
    clearTimeout(this.debounce);
    if (!q.trim()) return this.found = null;
    this.debounce = setTimeout(() => {
      app.store.find('curio-items', {
        filter: {
          q: q.trim()
        },
        include: 'collection.user,collection.type',
        page: {
          limit: 24
        }
      }).then(items => {
        if (this.q === q) this.found = items;
        m.redraw();
      });
    }, 300);
  }
  view() {
    const chosen = this.typeId && app.store.getById('curio-types', this.typeId);
    return m(PageStructure, {
      className: "CurioBrowse",
      sidebar: () => m(IndexSidebar, null)
    }, m("div", {
      className: "CurioBrowse-head"
    }, m("div", null, m("h2", null, t('browse.title')), this.overview ? m("p", null, t('browse.lead', {
      items: this.overview.items,
      members: this.overview.members
    })) : null), m("div", {
      className: "CurioBrowse-tools"
    }, m("div", {
      className: "Form-group CurioSearchField"
    }, m(Icon, {
      name: "fas fa-magnifying-glass"
    }), m("input", {
      className: "FormControl",
      type: "search",
      value: this.q,
      placeholder: text('browse.search'),
      "aria-label": text('browse.search'),
      oninput: e => this.search(e.target.value)
    })), app.session.user && app.forum.attribute('canCreateCurio') ? m(Button, {
      className: "Button Button--primary",
      icon: "fas fa-plus",
      onclick: () => addToMyCollection({})
    }, t('browse.add')) : null)), this.found ? this.results() : this.home(chosen));
  }
  results() {
    return m('[', null, m("div", {
      className: "CurioSection-heading"
    }, m("h2", null, t('browse.results', {
      q: this.q
    }))), this.found.length ? this.strip(this.found) : m(Placeholder, {
      text: t('browse.no_results')
    }));
  }
  home(chosen) {
    const counts = this.overview?.types || {};
    return m('[', null, !this.overview ? m(LoadingIndicator, {
      display: "block"
    }) : this.overview.layout === 'covers' ? this.coverTiles(counts) : this.tagTiles(counts), !chosen && this.recent && this.recent.length ? m('[', null, m("div", {
      className: "CurioSection-heading"
    }, m("h2", null, t('browse.recent'))), this.strip(this.recent)) : null, m("div", {
      className: "CurioSection-heading"
    }, m("h2", null, chosen ? label(chosen.names()) : m('[', null, m(Icon, {
      name: "fas fa-award"
    }), " ", t('browse.featured')))), this.collections === null ? m(LoadingIndicator, {
      display: "block"
    }) : this.collections.length ? m("div", {
      className: "CurioCards"
    }, this.collections.map(c => m("div", {
      className: "CurioCards-slot"
    }, collectionCard(c)))) : m(Placeholder, {
      text: t('browse.none')
    }));
  }

  /** The types as Flarum's tags page draws tags: coloured tiles, the latest collection along the foot. */
  tagTiles(counts) {
    return m("ul", {
      className: "TagTiles CurioTagTiles"
    }, this.shownTypes(counts).map(type => {
      const s = counts[type.id()] || {
        items: 0,
        collections: 0
      };
      const active = this.typeId === type.id();
      const latest = s.latest;
      return m("li", {
        className: 'TagTile colored ' + textContrastClass(type.color()) + (active ? ' active' : ''),
        style: {
          '--tag-bg': type.color()
        }
      }, m(Link, {
        className: "TagTile-info",
        href: active ? app.route('curio.browse') : app.route('curio.browse', {
          type: type.id()
        }),
        "aria-current": active ? 'true' : undefined
      }, m("div", {
        className: "TagTile-heading"
      }, m(Icon, {
        name: type.icon()
      }), m("h3", {
        className: "TagTile-name"
      }, label(type.names()))), m("p", {
        className: "TagTile-description"
      }, t('count.items', {
        count: s.items
      }), " \xB7 ", t('count.collections', {
        count: s.collections || 0
      }))), latest ? m(Link, {
        className: "TagTile-lastPostedDiscussion",
        href: collectionUrl({
          id: () => latest.id,
          slug: () => latest.slug
        })
      }, m("span", {
        className: "TagTile-lastPostedDiscussion-title"
      }, latest.name), latest.updatedAt ? humanTime(new Date(latest.updatedAt)) : null) : m("span", {
        className: "TagTile-lastPostedDiscussion"
      }));
    }));
  }

  /** The types as cover tiles: a strip of their latest covers over the name. */
  coverTiles(counts) {
    return m("div", {
      className: "CurioTypes",
      role: "list"
    }, this.shownTypes(counts).map(type => {
      const s = counts[type.id()] || {
        items: 0,
        covers: []
      };
      const active = this.typeId === type.id();
      return m("button", {
        type: "button",
        role: "listitem",
        className: 'CurioTypeTile' + (active ? ' active' : ''),
        style: {
          '--curio-accent': type.color()
        },
        "aria-pressed": active ? 'true' : 'false',
        onclick: () => {
          this.typeId = active ? null : type.id();
          this.loadCollections();
        }
      }, m("span", {
        className: "CurioTypeTile-covers"
      }, s.covers.length ? s.covers.map(url => m("img", {
        src: url,
        alt: "",
        loading: "lazy"
      })) : m(Icon, {
        name: type.icon(),
        className: "CurioTypeTile-empty"
      })), m("span", {
        className: "CurioTypeTile-body"
      }, m(Icon, {
        name: type.icon(),
        className: "CurioTypeTile-icon"
      }), m("strong", null, label(type.names())), m("span", null, t('count.items', {
        count: s.items
      }))));
    }));
  }

  /** Types that hold something, or every type while the forum has nothing yet (and the chosen one, always). */
  shownTypes(counts) {
    const all = types();
    const used = all.filter(type => (counts[type.id()]?.items || 0) > 0 || type.id() === this.typeId);
    return used.length ? used : all;
  }
  strip(items) {
    return m("ul", {
      className: "CurioStrip"
    }, items.map(item => {
      const user = item.collection()?.user();
      return m("li", null, m("button", {
        type: "button",
        onclick: () => app.modal.show(ItemModal, {
          itemId: item.id()
        })
      }, cover(item.coverUrl(), item.collection()?.type()?.shape(), false, item.displayTitle()), m("span", {
        className: "CurioItemCard-title"
      }, item.displayTitle()), user ? m("span", {
        className: "CurioStrip-owner"
      }, m(Avatar, {
        user: user
      }), " ", username(user)) : null));
    }));
  }
}
flarum.reg.add('ernestdefoe-curio', 'forum/components/BrowsePage', BrowsePage);